import{_ as t,o as a,c as o,ak as r}from"./chunks/framework.sV-XtlWr.js";const f=JSON.parse('{"title":"Offline export","description":"","frontmatter":{"title":"Offline export","lang":"en-US"},"headers":[],"relativePath":"offline-export.md","filePath":"offline-export.md","lastUpdated":1786027446000}'),n={name:"offline-export.md"};function i(s,e,d,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="offline-export" tabindex="-1">Offline export <a class="header-anchor" href="#offline-export" aria-label="Permalink to &quot;Offline export&quot;">​</a></h1><p>An investigation is only useful while someone can open it. Piwi can write a failing execution or a whole failure cluster to a file that opens with <strong>no network and no Piwi server</strong> — for a ticket attachment, a mail to someone without an account, or an archive that outlives your retention window.</p><p>The <strong>Export</strong> button sits on a test-case execution (<code>/test-run-cases/:id</code>) and on a failure cluster (<code>/failure-clusters/:id</code>).</p><h2 id="formats" tabindex="-1">Formats <a class="header-anchor" href="#formats" aria-label="Permalink to &quot;Formats&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Format</th><th>What you get</th></tr></thead><tbody><tr><td><strong>HTML</strong></td><td>One file. Screenshots and video are embedded as <code>data:</code> URIs; error, steps, console, network, ARIA snapshot, test source and the AI diagnosis are all inline. Double-click it.</td></tr><tr><td><strong>ZIP</strong></td><td><code>report.html</code> plus the raw artifacts on disk — full-size video, reconstructed <code>trace.zip</code> archives, console and network logs — and <code>data.json</code> with everything the report shows, machine-readable.</td></tr><tr><td><strong>PDF</strong></td><td>The HTML report opened with your browser&#39;s print dialog. Video and traces cannot survive printing; everything else does.</td></tr><tr><td><strong>Markdown / JSON</strong></td><td>Text only, for pasting into an issue or feeding an agent.</td></tr></tbody></table><p>A cluster export carries the most recent failing execution of each affected test.</p><h2 id="what-an-export-leaves-out-and-why-it-tells-you" tabindex="-1">What an export leaves out, and why it tells you <a class="header-anchor" href="#what-an-export-leaves-out-and-why-it-tells-you" aria-label="Permalink to &quot;What an export leaves out, and why it tells you&quot;">​</a></h2><p>Exports are bounded so one download cannot exhaust the server:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Bounds</th></tr></thead><tbody><tr><td><code>PIWI_EXPORT_MAX_INLINE_BYTES</code></td><td>8 MB</td><td>What a single HTML file will embed as a <code>data:</code> URI. Larger files stay out of the one-file HTML; the ZIP still carries them at full size.</td></tr><tr><td><code>PIWI_EXPORT_MAX_BYTES</code></td><td>500 MB</td><td>The whole export. Evidence is added largest-last until the budget is reached. The archive is built in memory, so this also bounds what one export costs the server.</td></tr><tr><td><code>PIWI_EXPORT_MAX_CASES</code></td><td>25</td><td>Member executions carrying full evidence in a cluster export. Remaining affected tests are listed by name.</td></tr></tbody></table><p>Anything left out is listed in an <strong>Omitted from this export</strong> table in the report and in the ZIP&#39;s <code>README.txt</code> — an export never drops evidence silently. Defaults and tuning: <a href="./configuration.html#offline-export">Configuration</a>.</p><h2 id="opening-a-hostile-report-safely" tabindex="-1">Opening a hostile report safely <a class="header-anchor" href="#opening-a-hostile-report-safely" aria-label="Permalink to &quot;Opening a hostile report safely&quot;">​</a></h2><p>The exported HTML carries a restrictive <code>Content-Security-Policy</code> and escapes every value that came from a test run, so a report is safe to open even when the failure it describes involved hostile page content.</p><h2 id="reading-an-exported-trace" tabindex="-1">Reading an exported trace <a class="header-anchor" href="#reading-an-exported-trace" aria-label="Permalink to &quot;Reading an exported trace&quot;">​</a></h2><p>The ZIP carries reconstructed <code>trace.zip</code> archives, but reading one still needs a Playwright trace viewer — <code>npx playwright show-trace trace.zip</code>, or the <a href="./evidence.html#trace-viewer">bundled viewer</a> on any Piwi instance. Bundling the viewer&#39;s assets into the export itself is on the <a href="https://github.com/PiwiTests/platform/blob/main/ROADMAP.md" target="_blank" rel="noreferrer">roadmap</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./evidence.html">Failure evidence</a> — what the export is a snapshot of</li><li><a href="./ai-diagnosis.html">AI diagnosis &amp; clustering</a> — cluster exports carry the diagnosis too</li><li><a href="./storage.html#data-retention">Storage configuration</a> — retention, and why an export outlives it</li></ul>',16)])])}const u=t(n,[["render",i]]);export{f as __pageData,u as default};
